import React, { useState } from "react";
import { Modal, View, Text, TextInput, TouchableOpacity, StyleSheet, ScrollView } from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";

export default function NotaEditor({ mostraNotas }) {
  const [texto, setTexto] = useState("");
  const [modalVisivel, setModalVisivel] = useState(false);

  async function salvanota() {
    if (!texto.trim()) {
      alert("Por favor, digite algum texto para a nota.");
      return;
    }

    try {
      const novoId = await geraId();
      const umaNota = {
        id: novoId.toString(),
        texto: texto,
      };
      console.log("Salvando nota:", umaNota);

      await AsyncStorage.setItem(umaNota.id, umaNota.texto);
      setTexto("");
      setModalVisivel(false);
      mostraNotas();
    } catch (error) {
      console.error("Erro ao salvar nota:", error);
      alert("Erro ao salvar a nota.");
    }
  }

  async function geraId() {
    try {
      const todasChaves = await AsyncStorage.getAllKeys();
      console.log("Chaves para gerar ID:", todasChaves);

      if (todasChaves.length <= 0) {
        return 1;
      }

      const idsNumericos = todasChaves
        .map((key) => parseInt(key))
        .filter((id) => !isNaN(id));

      if (idsNumericos.length === 0) {
        return 1;
      }

      return Math.max(...idsNumericos) + 1;
    } catch (error) {
      console.error("Erro ao gerar ID:", error);
      return Date.now(); // Fallback com timestamp
    }
  }

  return (
    <>
      <Modal
        animationType="slide"
        transparent={true}
        visible={modalVisivel}
        onRequestClose={() => {
          setModalVisivel(false);
        }}
      >
        <View style={estilos.centralizaModal}>
          <ScrollView showsVerticalScrollIndicator={false}>
            <View style={estilos.modal}>
              <Text style={estilos.modalTitulo}>Criar nota</Text>
              <Text style={estilos.modalSubTitulo}>Conteúdo da nota</Text>
              <TextInput
                style={estilos.modalInput}
                multiline={true}
                numberOfLines={4}
                onChangeText={(novoTexto) => setTexto(novoTexto)}
                placeholder="Digite aqui seu lembrete"
                value={texto}
              />
              <View style={estilos.modalBotoes}>
                <TouchableOpacity
                  style={estilos.modalBotaoSalvar}
                  onPress={salvanota}
                >
                  <Text style={estilos.modalBotaoTexto}>Salvar</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={estilos.modalBotaoCancelar}
                  onPress={() => {
                    setModalVisivel(false);
                    setTexto("");
                  }}
                >
                  <Text style={estilos.modalBotaoTexto}>Cancelar</Text>
                </TouchableOpacity>
              </View>
            </View>
          </ScrollView>
        </View>
      </Modal>

      <TouchableOpacity
        onPress={() => {
          setModalVisivel(true);
        }}
        style={estilos.adicionarMemo}
      >
        <Text style={estilos.adicionarMemoTexto}>+</Text>
      </TouchableOpacity>
    </>
  );
}

const estilos = StyleSheet.create({
  centralizaModal: {
    flex: 1,
    flexDirection: "row",
    alignItems: "flex-end",
  },
  modal: {
    backgroundColor: "#FFFFFF",
    paddingHorizontal: 16,
    paddingTop: 16,
    paddingBottom: 32,
    marginTop: 8,
    marginHorizontal: 16,
    borderTopLeftRadius: 8,
    borderTopRightRadius: 8,
    shadowColor: "#000",
    shadowOffset: {
      width: 0,
      height: 5,
    },
    shadowOpacity: 0.34,
    shadowRadius: 6.27,
    elevation: 10,
  },
  modalTitulo: {
    fontSize: 28,
    fontWeight: "600",
    marginBottom: 18,
  },
  modalInput: {
    fontSize: 18,
    marginBottom: 12,
    paddingHorizontal: 8,
    paddingVertical: 8,
    borderBottomWidth: 1,
    borderBottomColor: "#FF9A94",
    minHeight: 100,
    textAlignVertical: "top",
  },
  modalSubTitulo: {
    fontSize: 14,
    marginBottom: 8,
    fontWeight: "600",
  },
  modalBotoes: {
    flexDirection: "row",
    justifyContent: "space-between",
    marginTop: 16,
  },
  modalBotaoSalvar: {
    backgroundColor: "#2ea805",
    borderRadius: 5,
    padding: 12,
    width: 100,
    alignItems: "center",
  },
  modalBotaoCancelar: {
    backgroundColor: "#057fa8",
    borderRadius: 5,
    padding: 12,
    width: 100,
    alignItems: "center",
  },
  modalBotaoTexto: {
    color: "#FFFFFF",
    fontWeight: "bold",
  },
  adicionarMemo: {
    backgroundColor: "#54ba32",
    justifyContent: "center",
    height: 64,
    width: 64,
    margin: 16,
    alignItems: "center",
    borderRadius: 32,
    position: "absolute",
    bottom: 0,
    right: 0,
    shadowColor: "#000",
    shadowOffset: {
      width: 0,
      height: 2,
    },
    shadowOpacity: 0.23,
    shadowRadius: 2.62,
    elevation: 4,
  },
  adicionarMemoTexto: {
    fontSize: 32,
    lineHeight: 40,
    color: "#FFFFFF",
  },
});
